function showToast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function addJournal(title,text){if(save.journal.some(x=>x.title===title))return;save.journal.push({title,text});persist();}
function near(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)===1}
function move(dx,dy){if(!game||game.won)return;const x=game.player.x+dx,y=game.player.y+dy,t=tile(x,y);if(t==='#')return;if(t==='D'&&!gateOpen()){showToast('THE STONE GATE IS SEALED');return}if(t==='~'&&!game.water){showToast('THE CHANNEL IS TOO DEEP');return}if(t==='G'){showToast('THE SENTINEL BLOCKS THE WAY');return}if(t==='>'&&!game.clue){showToast('THE INSCRIPTION IS STILL UNREAD');return}if(t==='>'&&!gateOpen()){showToast('THE INNER MECHANISM IS STILL LOCKED');return}game.player={x,y};game.moves++;if(t==='C'&&!game.clue){game.clue=true;let l=LEVELS[levelIndex];addJournal(l.clue,l.text);showToast('EVIDENCE ADDED TO YOUR JOURNAL');}if(t==='A'&&!game.artifact){game.artifact=true;save.found[levelIndex]=true;persist();showToast('HIDDEN RELIC RECOVERED · +1 STAR');}if(t==='K'){game.key=true;setTile(x,y,'.');showToast('BRONZE KEY ACQUIRED');}if(t==='P'){game.plate=true;showToast('THE PRESSURE PLATE CLICKS');}if(t==='T'&&game.moves%3===0){showToast('A DART TRAP FIRES — STEP BACK');game.player={...game.start};game.deaths++;}if(game.guardian){moveGuardian();if(game.guardian&&game.guardian.x===game.player.x&&game.guardian.y===game.player.y){showToast('THE SENTINEL STRIKES — BACK TO THE ENTRANCE');game.player={...game.start};game.deaths++;}}if(t==='>'&&game.clue&&gateOpen())winLevel();render();}
function gateOpen(){let typ=LEVELS[levelIndex].type;return typ==='trail'||typ==='key'&&game.key||typ==='plate'&&game.plate||typ==='mirror'&&game.mirror||typ==='water'&&game.water||typ==='guardian'&&game.plate||typ==='sequence'&&game.mechanism||typ==='shadow'&&game.secret||typ==='final'&&game.plate||typ==='ending'&&game.answer}
function moveGuardian(){let g=game.guardian,p=game.player;let cand=[[g.x+1,g.y],[g.x-1,g.y],[g.x,g.y+1],[g.x,g.y-1]].filter(([x,y])=>tile(x,y)!=='#'&&tile(x,y)!=='D'&&tile(x,y)!=='~'&&!(x===g.x&&y===g.y));cand.sort((a,b)=>Math.abs(a[0]-p.x)+Math.abs(a[1]-p.y)-Math.abs(b[0]-p.x)-Math.abs(b[1]-p.y));if(cand.length){let [x,y]=cand[0];game.guardian={x,y}}}
function interact(){if(!game||game.won)return;let l=LEVELS[levelIndex],p=game.player;let around=[[p.x,p.y],[p.x+1,p.y],[p.x-1,p.y],[p.x,p.y+1],[p.x,p.y-1]].map(([x,y])=>({x,y,t:tile(x,y)}));let target=around.find(a=>a.t==='M'||a.t==='X'||a.t==='L');if(!target){showToast('NOTHING HERE TO EXAMINE');return}
if(l.type==='mirror'&&(target.t==='M'||target.t==='L')){game.mirror=!game.mirror;if(game.mirror){game.mechanism=true;showToast('THE RAY STRIKES THE SUN SEAL');}else showToast('THE MIRROR TURNS');render();return}
if(l.type==='water'){if(target.t==='X'){game.water=true;game.mechanism=true;showToast('THE EASTERN CHANNEL BEGINS TO DRAIN');render();return}}
if(l.type==='sequence'){if(target.t==='X'){openChoice('Decode the inscription','Which sequence matches the margin marks?',['Moon → River → Sun','Sun → Moon → River','River → Sun → Moon'],0,()=>{game.mechanism=true;game.answer=true;showToast('THE BOOK-DOOR OPENS');render()},()=>showToast('THE STONE REMAINS SILENT'));return}}
if(l.type==='shadow'){if(target.t==='X'){game.secret=true;game.mechanism=true;addJournal('A passage in shadow','The floor’s negative space points to the archivist’s hidden route. Someone expected the family signet to return.');showToast('A HIDDEN PASSAGE IS REVEALED');render();return}}
if(l.type==='ending'){if(target.t==='X'){openChoice('The Orison covenant','What will Evelyn choose to do with the sanctuary?',['Remember · share the truth','Protect · keep it hidden','Return · leave the choice to Adrian'],0,(choice)=>{game.answer=true;game.mechanism=true;save.ending=choice;persist();render();winLevel()},choice=>{game.answer=true;save.ending=choice;persist();winLevel()});return}}
if(l.type==='final'&&target.t==='X'){showToast('THE FINAL GATE WAITS FOR THE LISTENING STONE');return}showToast('THE MECHANISM DOES NOT RESPOND');}
function openChoice(title,desc,options,correct,onCorrect,onWrong){let root=$('#modalRoot');root.innerHTML=`<div class="modal"><button class="modal-close" aria-label="Close">×</button><div class="modal-kicker">Field investigation</div><h2>${title}</h2><p>${desc}</p><div class="journal-list">${options.map((o,i)=>`<button class="chapter-card choice" data-choice="${i}"><strong>${o}</strong><small>Examine this interpretation</small></button>`).join('')}</div></div>`;root.classList.remove('hidden');root.querySelector('.modal-close').onclick=()=>root.classList.add('hidden');root.querySelectorAll('.choice').forEach(b=>b.onclick=()=>{let n=+b.dataset.choice;root.classList.add('hidden');if(title.includes('covenant'))onCorrect(n);else if(n===correct)onCorrect(n);else onWrong(n)});}
function winLevel(){if(game.won)return;game.won=true;const l=LEVELS[levelIndex];let stars=1+(game.clue?1:0)+(game.artifact?1:0)+(game.moves<=l.target?1:0);stars=Math.min(3,stars);save.completed[levelIndex]=Math.max(stars,save.completed[levelIndex]||0);save.unlocked=Math.max(save.unlocked,Math.min(levelIndex+1,LEVELS.length-1));if(l.chapter<CHAPTERS.length&&(!save.journal.some(x=>x.title===CHAPTERS[l.chapter].name)))addJournal(CHAPTERS[l.chapter].name,CHAPTERS[l.chapter].reveal);persist();render();let last=levelIndex===LEVELS.length-1;let root=$('#modalRoot');root.innerHTML=`<div class="modal"><div class="modal-kicker">${last?'The expedition is complete':'Chamber cleared'}</div><h2>${last?'Beneath the silence':l.name+' · Complete'}</h2><div class="reward-stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p>${last?CHAPTERS[4].reveal:'Evidence secured. The path forward is open.'}</p><div class="journal-entry"><strong>${last?'A new beginning':'Expedition record'}</strong><p>${last?`Evelyn’s choice: ${['Remember','Protect','Return'][save.ending||0]}. The sanctuary’s story is now part of her journal.`:`${game.moves} steps · ${game.artifact?'Hidden relic recovered':'One optional relic remains'} · ${game.clue?'Field evidence recovered':'Evidence missed'}`}</p></div><div class="button-row" style="margin-top:18px"><button class="primary" id="nextBtn">${last?'Review journal':'Continue'} →</button><button class="secondary" id="mapBtn">Expedition map</button></div></div>`;root.classList.remove('hidden');$('#nextBtn').onclick=()=>{root.classList.add('hidden');if(last)openJournal();else loadLevel(Math.min(levelIndex+1,LEVELS.length-1))};$('#mapBtn').onclick=()=>showLevels();}
function openJournal(){let root=$('#modalRoot');let entries=save.journal;root.innerHTML=`<div class="modal"><button class="modal-close" aria-label="Close">×</button><div class="modal-kicker">Evelyn Cross · field journal</div><h2>Evidence &amp; recollections</h2><p>Every recovered note changes what Evelyn knows about the vanished Orison—and about her own family.</p><div class="journal-list">${entries.length?entries.map(e=>`<div class="journal-entry"><strong>${esc(e.title)}</strong><p>${esc(e.text)}</p></div>`).join(''):'<p class="locked-note">No evidence recovered yet. Look for letters, carvings, and objects marked in gold.</p>'}</div><div class="modal-kicker" style="margin-top:20px">Rewards</div><p>${Object.keys(save.completed).length} chambers cleared · ${Object.keys(save.found).length} hidden relics · Outfit: ${save.outfit?'Desert archivist':'Field archaeologist'}${Object.keys(save.found).length>=3?' · Archivist’s wrap unlocked!':''}</p></div>`;root.classList.remove('hidden');root.querySelector('.modal-close').onclick=()=>root.classList.add('hidden');}
function showLevels(){let root=$('#modalRoot');root.innerHTML=`<div class="modal"><button class="modal-close" aria-label="Close">×</button><div class="modal-kicker">Select a route</div><h2>The expedition</h2><p>Five worlds. Ten chambers. Each cleared path reveals another fragment of Adrian’s disappearance.</p><div class="chapter-grid">${CHAPTERS.map((c,i)=>{let first=LEVELS.findIndex(l=>l.chapter===i),last=LEVELS.map(l=>l.chapter).lastIndexOf(i),isOpen=first<=save.unlocked;return `<button class="chapter-card" data-level="${Math.max(0,first)}" ${isOpen?'':'disabled'}><div class="chapter-no">${String(i+1).padStart(2,'0')} · ${isOpen?'UNLOCKED':'LOCKED'}</div><strong>${esc(c.name)}</strong><small>${esc(c.intro)}<br><br>${Object.keys(save.completed).filter(n=>+n>=first&&+n<=last).length} / ${last-first+1} chambers · ${isOpen?'Choose to begin':'Clear the previous route'}</small></button>`}).join('')}</div></div>`;root.classList.remove('hidden');root.querySelector('.modal-close').onclick=()=>root.classList.add('hidden');root.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{root.classList.add('hidden');loadLevel(+b.dataset.level)});}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function restart(){loadLevel(levelIndex);showToast('CHAMBER RESET')}
$('#beginBtn').onclick=()=>startGame(0);$('#continueBtn').onclick=()=>startGame(Math.min(save.unlocked,LEVELS.length-1));$('#continueBtn').disabled=Object.keys(save.completed).length===0;$('#levelsBtn').onclick=showLevels;$('#journalBtn').onclick=openJournal;$('#homeBtn').onclick=()=>{if(confirm('Return to the title screen? Your progress is saved.')){$('#gameScreen').classList.add('hidden');$('#titleScreen').classList.remove('hidden')}};$('#restartBtn').onclick=restart;$('#hintBtn').onclick=()=>showToast('FIELD HINT · '+LEVELS[levelIndex].hint);$('#soundBtn').onclick=()=>{soundOn=!soundOn;$('#soundBtn').textContent=soundOn?'♫ ON':'♫';showToast(soundOn?'SOUND CUES ENABLED':'SOUND MUTED')};
$('#board').addEventListener('click',e=>{let g=e.target.closest('.tile-click');if(!g)return;let x=+g.dataset.x,y=+g.dataset.y,dx=x-game.player.x,dy=y-game.player.y;if(Math.abs(dx)+Math.abs(dy)===1)move(dx,dy);else if(x===game.player.x&&y===game.player.y)interact()});
document.addEventListener('keydown',e=>{if($('#modalRoot').classList.contains('hidden')===false){if(e.key==='Escape')$('#modalRoot').classList.add('hidden');return}let d={ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1],ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0]}[e.key];if(d){e.preventDefault();move(...d)}else if(e.key.toLowerCase()==='e'||e.key===' '){e.preventDefault();interact()}else if(e.key.toLowerCase()==='r'){restart()}});
document.querySelectorAll('.touch-controls button').forEach(b=>b.onclick=()=>{let d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[b.dataset.dir];move(...d)});
let touchStart=null;$('#board').addEventListener('touchstart',e=>{let t=e.changedTouches[0];touchStart=[t.clientX,t.clientY]},{passive:true});$('#board').addEventListener('touchend',e=>{if(!touchStart)return;let t=e.changedTouches[0],dx=t.clientX-touchStart[0],dy=t.clientY-touchStart[1];touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))<28)return;if(Math.abs(dx)>Math.abs(dy))move(dx>0?1:-1,0);else move(0,dy>0?1:-1)},{passive:true});
// Correct movement keys for lowercase and provide a graceful first-run save.
if(!localStorage.getItem('shadows-save'))persist();
</script></body></html>

