 <script>
+const chapters=[
+ {name:'Forgotten Expedition',place:'The overgrown camp',levels:['The Empty Camp','Surveyor’s Trail']},
+ {name:'Temple of Echoes',place:'A voice in the stone',levels:['Threshold of Whispers','The Listening Hall']},
+ {name:'Sunken City',place:'Beneath the green water',levels:['Drowned Market','The Tide Engine']},
+ {name:'Library of Shadows',place:'A history erased',levels:['The Scriptorium','Archive of Names']},
+ {name:'Lost Sanctuary',place:'Where the trail ends',levels:['The Heart Chamber','Adrian’s Choice']}
+];
+const stories=[
+ ['Adrian’s abandoned camp is still warm. His field book ends with a sketch of a three-eyed sun.','A brass survey marker bears Adrian’s initials—and points toward a temple hidden beyond the ridge.'],
+ ['The threshold answers each footstep with a different note. Adrian knew the melody, but left its final measure for you.','A mural shows the first keepers sealing something away, not worshipping it.'],
+ ['The city sank in a single night. A waterlogged letter says the keepers chose to flood it.','The tide engine is still turning. Its inscription warns: “A door opened cannot be made unknown.”'],
+ ['The library’s shelves hold blank books. A name has been cut from every spine.','You find Adrian’s most recent note: “The sanctuary is real. I can’t let them take what’s inside.”'],
+ ['At the sanctuary, Adrian’s bootprints stop at a sealed door. His journal is beside it.','Adrian is alive beyond the door. He asks you to help decide whether the truth should leave this place.']
+];
+const levels=chapters.flatMap((c,ci)=>c.levels.map((name,li)=>({name,chapter:ci,subtitle:c.place,story:stories[ci][li],par:24+ci*2+li*3,start:[0,6],exit:[6,0],clue:[2+(ci+li)%3,4],relic:[4,2+(li%2)],lever:[1+(ci%3),2+(li%2)],hazards:[[3,3],[5,4]],walls:[[1,5],[2,5],[4,5],[5,5],[3,2]],plate:[5,1]})));
+const svgNS='http://www.w3.org/2000/svg';const $=s=>document.querySelector(s);
+let state={level:0,pos:[0,6],moves:0,clues:[],relics:[],lever:false,plate:false,won:[],journal:[],sound:true};let toastTimer;
