+function save(){try{localStorage.setItem('lostTempleSave',JSON.stringify(state))}catch(e){}}
+function current(){return levels[state.level]||levels[0]}function same(a,b){return a[0]===b[0]&&a[1]===b[1]}function sEl(tag,attrs={},text){const e=document.createElementNS(svgNS,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e}
+function showGame(){$('#titleScreen').classList.add('hidden');$('#gameScreen').classList.remove('hidden');draw()}
+function startGame(){state.level=0;state.pos=[...levels[0].start];state.moves=0;state.clues=[];state.relics=[];state.lever=false;state.plate=false;showGame();save()}
